    "hypothesis": {
      "value": "RF-EMF exposure alters postsynaptic structure and hinders neurite outgrowth in developing hippocampal neurons of early postnatal mice.",
      "verification_status": "reported",
      "evidence": [
        {
          "block_id": "b00027",
          "quote": "Collectively, these data suggest that hindered neuronal outgrowth following RF-EMF exposure may decrease overall synaptic density during early neurite development of hippocampal neurons."
        }
      ]
    },
    "primary_outcome": {
      "value": "Changes in dendritic spines, glutamate receptors, BDNF expression, PSD95 puncta, neurite outgrowth, and memory function.",
      "verification_status": "reported",
      "evidence": [
        {
          "block_id": "b00027",
          "quote": "The total number of dendritic spines showed statistically significant decreases in the dentate gyrus (DG) but was not altered in the cornu ammonis (CA1) in hippocampal neurons."
        },
        {
          "block_id": "b00042",
          "quote": "The number of mushroom-type DSs showed statistically significant decreases in both CA1 (Cohen’s d = 0.71) and DG (Cohen’s d = 1.03)"
        },
        {
          "block_id": "b00046",
          "quote": "The total expression of AMPA and NMDA receptors in the hippocampus was statistically significantly decreased in the hippocampus of mice following RF-EMF exposure"
        },
        {
          "block_id": "b00054",
          "quote": "BDNF expression levels showed a statistically significant decrease in the hippocampus of mice following RF-EMF exposure"
        },
        {
          "block_id": "b00060",
          "quote": "The number of PSD95 puncta increased with time from DIV 3 to 9 and reached a peak on DIV 9. In the RF-EMF-exposed group, although the number of PSD95 puncta also gradually increased over time, it was significantly lower in statistical analysis on DIV 5, 7, and 9 compared to that in control cells"
        },
        {
          "block_id": "b00076",
          "quote": "Neurite length increased with time from DIV 3 to DIV 9 and reached a peak on DIV 9. In the RF-EMF-exposed group, neurite length also increased with time but to a lesser extent than that in control cells"
        },
        {
          "block_id": "b00079",
          "quote": "The memory index (Cohen’s d = 0.58) and discrimination ratio (Cohen’s d = 0.58) showed statistically significant decreases in RF-EMF-exposed mice"
        }
      ]
    },
